export const BASELINE_DICTIONARIES: Record<string, Record<string, any>> = {
  ar: AR_DICT,
  en: EN_DICT,
  fr: FR_DICT,
  de: DE_DICT,
  es: ES_DICT,
  it: IT_DICT,
  tr: TR_DICT,
  pt: PT_DICT,
  ru: RU_DICT,
  ja: JA_DICT,
  zh: ZH_DICT,
  hi: HI_DICT,
};

function resolveKeyInDicts(key: string, lang: string = 'ar', customFallback?: string): string {
  if (!key || typeof key !== 'string') return customFallback || '';

  const safeLang = (typeof lang === 'string' && lang.trim()) ? lang : 'ar';
  const targetDict = (typeof BASELINE_DICTIONARIES !== 'undefined' && BASELINE_DICTIONARIES[safeLang])
    ? BASELINE_DICTIONARIES[safeLang]
    : ((typeof BASELINE_DICTIONARIES !== 'undefined' && BASELINE_DICTIONARIES.ar) ? BASELINE_DICTIONARIES.ar : {});

  // 1. Direct Target Dictionary Check
  if (targetDict && targetDict[key] !== undefined && typeof targetDict[key] === 'string' && targetDict[key].trim() !== '') {
    return targetDict[key];
  }

  // Dot-notation support
  if (key.includes('.')) {
    const parts = key.split('.');
    let curr: any = targetDict;
    for (const p of parts) {
      if (curr && typeof curr === 'object' && p in curr) {
        curr = curr[p];
      } else {
        curr = undefined;
        break;
      }
    }
    if (typeof curr === 'string' && curr.trim() !== '') return curr;
  }

  // 2. English Fallback (for non-English targets)
  if (safeLang !== 'en' && typeof BASELINE_DICTIONARIES !== 'undefined' && BASELINE_DICTIONARIES.en && BASELINE_DICTIONARIES.en[key]) {
    return BASELINE_DICTIONARIES.en[key];
  }

  // 3. Arabic Baseline Fallback (for non-Arabic targets)
  if (safeLang !== 'ar' && typeof BASELINE_DICTIONARIES !== 'undefined' && BASELINE_DICTIONARIES.ar && BASELINE_DICTIONARIES.ar[key]) {
    return BASELINE_DICTIONARIES.ar[key];
  }

  // 4. Custom Fallback provided in component call
  if (customFallback && typeof customFallback === 'string' && customFallback.trim() !== '') {
    return customFallback;
  }

  return '';
}

function createSafeTranslationProxy(langCode: string = 'ar') {
  const safeLang = (typeof langCode === 'string' && langCode.trim()) ? langCode : 'ar';
  const targetDict = (typeof BASELINE_DICTIONARIES !== 'undefined' && BASELINE_DICTIONARIES[safeLang])
    ? BASELINE_DICTIONARIES[safeLang]
    : ((typeof BASELINE_DICTIONARIES !== 'undefined' && BASELINE_DICTIONARIES.ar) ? BASELINE_DICTIONARIES.ar : {});

  const translateFn = (key?: any, fallbackOrReplacements?: Record<string, any> | string, replacementsObj?: Record<string, any>): string => {
    try {
      if (!key) return '';
      if (typeof key !== 'string') {
        try {
          return String(key);
        } catch {
          return '';
        }
      }

      let customFallback: string | undefined;
      let replacements: Record<string, any> | undefined;

      if (typeof fallbackOrReplacements === 'string') {
        customFallback = fallbackOrReplacements;
        replacements = replacementsObj;
      } else if (typeof fallbackOrReplacements === 'object') {
        replacements = fallbackOrReplacements;
      }

      let val = resolveKeyInDicts(key, safeLang, customFallback);

      if (!val && customFallback) {
        val = customFallback;
      }

      if (replacements && typeof replacements === 'object') {
        Object.keys(replacements).forEach((rKey) => {
          try {
            val = val.replace(new RegExp(`\\{${rKey}\\}|%${rKey}%`, 'g'), String(replacements[rKey] ?? ''));
          } catch {
            // Ignore replacement error
          }
        });
      }
      return typeof val === 'string' ? val : String(val || '');
    } catch (err) {
      console.error('Translation fn error caught safely:', err);
      return typeof key === 'string' ? key : '';
    }
  };

  return new Proxy(translateFn as any, {
    get(target, prop: string | symbol) {
      if (typeof prop !== 'string') return (target as any)[prop];

      if (
        prop === 'then' ||
        prop === 'catch' ||
        prop === 'finally' ||
        prop === 'toJSON' ||
        prop === '$typeof' ||
        prop === 'nodeType' ||
        prop === 'displayName' ||
        prop === 'prototype' ||
        prop === 'constructor' ||
        prop === 'length' ||
        prop === 'name' ||
        prop === 'toString' ||
        prop === 'valueOf'
      ) {
        return (target as any)[prop];
      }

      if (prop in target && (target as any)[prop] !== undefined) {
        return (target as any)[prop];
      }

      if (targetDict && prop in targetDict && targetDict[prop] !== undefined && typeof targetDict[prop] === 'string' && targetDict[prop].trim() !== '') {
        return targetDict[prop];
      }

      try {
        const res = resolveKeyInDicts(prop, safeLang);
        return typeof res === 'string' ? res : String(res || '');
      } catch {
        return prop;
      }
    },
    apply(target, thisArg, argArray) {
      try {
        return translateFn(argArray[0], argArray[1], argArray[2]);
      } catch (err) {
        console.error('Translation apply error caught safely:', err);
        return String(argArray[0] || '');
      }
    }
  });
}

export const MULTI_TRANSLATIONS: Record<string, any> = new Proxy(BASELINE_DICTIONARIES, {
  get(target, prop: string | symbol) {
    if (
      typeof prop !== 'string' ||
      prop === 'then' ||
      prop === 'catch' ||
      prop === 'finally' ||
      prop === 'toJSON' ||
      prop === '$typeof' ||
      prop === 'constructor' ||
      prop === 'prototype'
    ) {
      return (target as any)[prop];
    }
    return createSafeTranslationProxy(prop);
  }
});

export const DEFAULT_GLOBAL_TRANSLATION_PROXY = createSafeTranslationProxy('ar');
export const t = DEFAULT_GLOBAL_TRANSLATION_PROXY;
if (typeof window !== 'undefined') {
  (window as any).t = DEFAULT_GLOBAL_TRANSLATION_PROXY;
}
if (typeof globalThis !== 'undefined') {
  (globalThis as any).t = DEFAULT_GLOBAL_TRANSLATION_PROXY;
}

export function updateGlobalTranslationProxy(lang: string = 'ar') {
  const proxy = createSafeTranslationProxy(lang);
  if (typeof window !== 'undefined') {
    (window as any).t = proxy;
  }
  if (typeof globalThis !== 'undefined') {
    (globalThis as any).t = proxy;
  }
  return proxy;
}

export function getTranslation(lang?: string | AppLanguage | null): any {
  try {
    const proxy = createSafeTranslationProxy(lang || 'ar');
    updateGlobalTranslationProxy(lang || 'ar');
    return proxy;
  } catch (e) {
    console.error('getTranslation error caught safely:', e);
    return DEFAULT_GLOBAL_TRANSLATION_PROXY;
  }
}

export function getHabitDisplayName(habit: { id?: string; name: string; nameKey?: string } | undefined | null, t?: any): string {
  if (!habit) return '';
  const trans = t || (typeof window !== 'undefined' && (window as any).t) || DEFAULT_GLOBAL_TRANSLATION_PROXY;
  if (habit.nameKey && trans[habit.nameKey]) return trans[habit.nameKey];
  if (habit.id === 'habit-1' || habit.name === 'شرب 2 لتر ماء دافئ' || habit.name === 'Drink 2L warm water') return trans.defaultHabit1Name || habit.name;
  if (habit.id === 'habit-2' || habit.name === 'تأمل واسترخاء العضلات (10 د)' || habit.name === 'Meditation & muscle relaxation (10m)') return trans.defaultHabit2Name || habit.name;
  if (habit.id === 'habit-3' || habit.name === 'المشي السريع أو تمرين منزلي' || habit.name === 'Brisk walk or home workout') return trans.defaultHabit3Name || habit.name;
  if (habit.id === 'habit-4' || habit.name === 'قراءة في كتاب النفس السلوكي' || habit.name === 'Reading a CBT psychology book') return trans.defaultHabit4Name || habit.name;
  return habit.name;
}

export function getReminderDisplayName(rem: { id?: string; title: string } | undefined | null, t?: any): string {
  if (!rem) return '';
  const trans = t || DEFAULT_GLOBAL_TRANSLATION_PROXY;
  if (rem.id === 'rem-1') return trans.defaultReminder1Title || rem.title;
  if (rem.id === 'rem-2') return trans.defaultReminder2Title || rem.title;
  if (rem.id === 'rem-3') return trans.defaultReminder3Title || rem.title;
  return rem.title;
}

export interface LanguageContextType {
  currentLanguage: AppLanguage;
  setLanguage: (lang: AppLanguage | string) => void;
  t: any;
  isRTL: boolean;
}

const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

export function LanguageProvider({ children, initialLanguage = 'ar' }: { children: ReactNode; initialLanguage?: AppLanguage; }) {
  const [currentLanguage, setCurrentLanguageState] = useState<AppLanguage>(initialLanguage);

  const setLanguage = (lang: string) => {
    const validLang = (SUPPORTED_LANGUAGES.some((l) => l.code === lang) ? lang : 'ar') as AppLanguage;
    setCurrentLanguageState(validLang);
    try {
      if (typeof document !== 'undefined') {
        document.documentElement.lang = validLang;
        document.documentElement.dir = isRtlLanguage(validLang) ? 'rtl' : 'ltr';
      }
    } catch {}
  };

  const isRTL = currentLanguage === 'ar';

  const t = createSafeTranslationProxy(currentLanguage);
  updateGlobalTranslationProxy(currentLanguage);

  return React.createElement(LanguageContext.Provider, { value: { currentLanguage, setLanguage, t, isRTL } }, children);
}

export function useLanguage(): LanguageContextType {
  const context = useContext(LanguageContext);
  if (context) return context;

  return {
    currentLanguage: 'ar',
    setLanguage: () => {},
    t: createSafeTranslationProxy('ar'),
    isRTL: true
  };
}
